CREATE TABLE IF NOT EXISTS doctors (id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,specialization VARCHAR(120) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(160) NOT NULL,availability TEXT NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS appointments (id SERIAL PRIMARY KEY,patient_name VARCHAR(120) NOT NULL,patient_contact VARCHAR(80) NOT NULL,doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE RESTRICT,date_time TIMESTAMP NOT NULL,reason TEXT NOT NULL,status VARCHAR(30) NOT NULL CHECK(status IN ('pending','confirmed','completed','cancelled')));
